import { Button, LayerCard } from "@cloudflare/kumo";
import { useState } from "react";

import { authClient } from "~/features/auth/api/auth-client";

export function ConsentPage({
  claimsQuery,
  clientId,
  scope,
}: Readonly<{
  claimsQuery?: string;
  clientId?: string;
  scope?: string;
}>) {
  const [isPending, setIsPending] = useState(false);
  const [error, setError] = useState<string>();
  const scopes = scope?.split(/\s+/).filter(Boolean) ?? [];
  const claims = readClaimNames(claimsQuery);

  async function submitConsent(accept: boolean) {
    setError(undefined);
    setIsPending(true);
    try {
      const result = await authClient.$fetch("/oauth2/consent", {
        body: { accept },
        method: "POST",
      });
      if (result.error) throw new Error(result.error.message || "The consent request failed.");
      const payload = result.data as {
        redirect_uri?: unknown;
        redirect?: unknown;
        url?: unknown;
      } | null;
      const redirectUri =
        typeof payload?.redirect_uri === "string"
          ? payload.redirect_uri
          : payload?.redirect === true && typeof payload.url === "string"
            ? payload.url
            : undefined;
      if (typeof redirectUri !== "string") throw new Error("The consent response was incomplete.");
      window.location.assign(redirectUri);
    } catch (submitError) {
      setError(submitError instanceof Error ? submitError.message : "The consent request failed.");
      setIsPending(false);
    }
  }

  return (
    <section className="mx-auto max-w-2xl px-5 py-14 sm:px-8 sm:py-20">
      <p className="text-sm font-medium uppercase text-(--tangerine)">Authorization</p>
      <h1 className="mt-4 font-display text-5xl font-semibold leading-none text-kumo-strong">
        Give access with confidence.
      </h1>
      <LayerCard className="mt-10 bg-kumo-elevated px-5 py-4 ring ring-kumo-line">
        <h2 className="text-2xl font-semibold text-kumo-strong">
          {clientId ? `${clientId} requests access` : "An application requests access"}
        </h2>
        <p className="mt-2 text-sm text-kumo-subtle">
          Review the requested permissions before continuing.
        </p>
        <ul className="mt-6 space-y-3 text-sm text-kumo-default">
          {scopes.length > 0 ? (
            scopes.map((requestedScope) => (
              <li
                className="rounded-lg border border-kumo-hairline bg-kumo-recessed p-3"
                key={requestedScope}
              >
                {requestedScope}
              </li>
            ))
          ) : (
            <li className="rounded-lg border border-kumo-hairline bg-kumo-recessed p-3">
              No scopes were requested.
            </li>
          )}
        </ul>
        {claims.length > 0 ? (
          <>
            <p className="mt-6 text-sm font-medium text-kumo-strong">Requested OIDC claims</p>
            <ul className="mt-3 space-y-3 text-sm text-kumo-default">
              {claims.map((claim) => (
                <li
                  className="rounded-lg border border-kumo-hairline bg-kumo-recessed p-3"
                  key={claim}
                >
                  {claim}
                </li>
              ))}
            </ul>
          </>
        ) : null}
        {error ? (
          <p className="mt-4 text-sm text-kumo-danger" role="alert">
            {error}
          </p>
        ) : null}
        <div className="mt-6 flex flex-col gap-3 sm:flex-row">
          <Button
            aria-busy={isPending}
            className="text-sm transition-none"
            disabled={isPending}
            onClick={() => void submitConsent(true)}
            type="button"
            variant="primary"
          >
            Allow access
          </Button>
          <Button
            className="w-full text-sm transition-none sm:w-auto"
            disabled={isPending}
            onClick={() => void submitConsent(false)}
            type="button"
            variant="ghost"
          >
            Cancel
          </Button>
        </div>
      </LayerCard>
    </section>
  );
}

function readClaimNames(value: string | undefined) {
  if (!value) return [];
  try {
    const parsed = JSON.parse(value) as Record<string, unknown>;
    return Object.entries(parsed).flatMap(([target, targetClaims]) =>
      targetClaims && typeof targetClaims === "object"
        ? Object.keys(targetClaims).map((claim) => `${target}.${claim}`)
        : [],
    );
  } catch {
    return [];
  }
}
import { createFileRoute } from "@tanstack/react-router";

import { ConsentPage } from "~/features/consent";

export const Route = createFileRoute("/consent")({
  validateSearch: (search) => ({
    claims: typeof search.claims === "string" ? search.claims : undefined,
    clientId: typeof search.client_id === "string" ? search.client_id : undefined,
    code: typeof search.code === "string" ? search.code : undefined,
    scope: typeof search.scope === "string" ? search.scope : undefined,
  }),
  component: ConsentRoute,
});

function ConsentRoute() {
  const { claims, clientId, scope } = Route.useSearch();
  return <ConsentPage claimsQuery={claims} clientId={clientId} scope={scope} />;
}
import { oauthProviderClient } from "@better-auth/oauth-provider/client";
import { createAuthClient } from "better-auth/client";

export const authClient = createAuthClient({
  plugins: [oauthProviderClient()],
});
import { drizzleAdapter } from "@better-auth/drizzle-adapter";
import { oauthProvider } from "@better-auth/oauth-provider";
import { betterAuth } from "better-auth/minimal";
import { jwt } from "better-auth/plugins/jwt";
import { and, eq, sql } from "drizzle-orm";
import { createDb } from "../db";
import * as authSchema from "../db/auth-schema";
import { auditEvents, humanPrincipals, principals } from "../db/domain-schema";
import { audienceResources, resolveShuiClaims } from "./modules/applications/claims";
import { consumeRateLimitBucket } from "./shared/infrastructure";

export type DevelopmentEmailKind = "invitation" | "password-reset" | "verification";

export interface DevelopmentEmailMessage {
  kind: DevelopmentEmailKind;
  email: string;
  token: string;
  url: string;
}

export const PASSWORD_RESET_TIMING_FLOOR_MS = 250;

const developmentEmailSink: DevelopmentEmailMessage[] = [];

export interface AuthEnvironment {
  DB: D1Database;
  BETTER_AUTH_SECRET: string;
  BETTER_AUTH_URL: string;
  BOOTSTRAP_TOKEN: string;
  DEV_EMAIL_SINK?: string;
  EMAIL_WEBHOOK_URL?: string;
}

export function readDevelopmentEmailSink(): readonly DevelopmentEmailMessage[] {
  return developmentEmailSink.slice();
}

export function clearDevelopmentEmailSink() {
  developmentEmailSink.length = 0;
}

export function recordDevelopmentEmail(
  environment: Pick<AuthEnvironment, "BETTER_AUTH_URL" | "DEV_EMAIL_SINK">,
  message: DevelopmentEmailMessage,
) {
  if (!isLocalEnvironment(environment)) return;

  developmentEmailSink.push(message);
  if (developmentEmailSink.length > 100) developmentEmailSink.shift();
}

export function isLocalEnvironment(
  environment: Pick<AuthEnvironment, "BETTER_AUTH_URL" | "DEV_EMAIL_SINK">,
) {
  return (
    environment.DEV_EMAIL_SINK === "true" &&
    (environment.BETTER_AUTH_URL.startsWith("http://localhost") ||
      environment.BETTER_AUTH_URL.startsWith("http://127.0.0.1"))
  );
}

export async function deliverEmail(
  environment: Pick<AuthEnvironment, "BETTER_AUTH_URL" | "DEV_EMAIL_SINK" | "EMAIL_WEBHOOK_URL">,
  message: DevelopmentEmailMessage,
) {
  if (isLocalEnvironment(environment)) {
    recordDevelopmentEmail(environment, message);
    return;
  }

  if (!environment.EMAIL_WEBHOOK_URL) {
    throw new Error("Transactional email delivery is not configured.");
  }

  const response = await fetch(environment.EMAIL_WEBHOOK_URL, {
    body: JSON.stringify(message),
    headers: { "content-type": "application/json" },
    method: "POST",
  });

  if (!response.ok) throw new Error(`Transactional email delivery failed: ${response.status}`);
}

export function createAuth(environment: AuthEnvironment) {
  const resourceIdentifier = `${environment.BETTER_AUTH_URL}/api`;
  const db = createDb(environment.DB);

  return betterAuth({
    appName: "Shui",
