      validateSearch: productSearchSchema,
    })

    const ProductList = () => {
      return (
        <div>
          <Link from={Route.fullPath} search={(prev) => ({ page: prev.page + 1 })}>
            Next Page
          </Link>
        </div>
      )
    }
